   <Input.Search aria-label="搜索知识" className="wiki-global-search" placeholder="搜索业务名、字段、指标……" value={search} onChange={e=>setSearch(e.target.value)} onSearch={()=>navigate(()=>performSearch())} enterButton={<SearchOutlined/>}/>
